using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.IO;
class RefreshTests{
 static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static void CheckSettingsLayout(CorePilot app){typeof(CorePilot).GetMethod("ShowPage",f).Invoke(app,new object[]{2});var content=(Panel)typeof(CorePilot).GetField("content",f).GetValue(app);var topology=content.Controls.OfType<Panel>().First(p=>p.Controls.OfType<Label>().Any(l=>l.Text=="处理器与 CCD 分组"));var labels=topology.Controls.OfType<Label>().ToArray();var title=labels.First(l=>l.Text=="处理器与 CCD 分组");var processor=labels.First(l=>l.Text=="处理器");var brand=labels.First(l=>l.Left==108&&l.Top==49);var group=labels.First(l=>l.Text=="核心分组");var ccd=labels.First(l=>l.Text.StartsWith("CCD0",StringComparison.Ordinal));var state=labels.First(l=>l.Text=="核对状态");var status=labels.First(l=>l.Text.StartsWith("已核对",StringComparison.Ordinal)||l.Text.StartsWith("未核对",StringComparison.Ordinal));Check(title.Left==processor.Left&&title.Font.Size>processor.Font.Size,"settings use distinct title and aligned label/value rows");Check(processor.Top==brand.Top&&group.Top==ccd.Top&&state.Top==status.Top&&processor.Left<brand.Left&&group.Left<ccd.Left&&state.Left<status.Left,"CPU, CCD mapping, and verification details align into columns");Check(content.Controls.OfType<Panel>().Any(p=>p.Controls.OfType<Label>().Any(l=>l.Text=="恢复行为")),"recovery guidance has its own labeled section");}
 static void CheckExitProgress(CorePilot app){var exit=(MotionButton)typeof(CorePilot).GetField("exitButton",f).GetValue(app);Check(exit!=null&&exit.Text=="退出并恢复","application has a visible exit-and-restore action");typeof(CorePilot).GetField("exitRequested",f).SetValue(app,true);var update=typeof(CorePilot).GetMethod("UpdateExitProgress",f);update.Invoke(app,new object[]{new CycleResult{PendingRecovery=2}});var state=(Label)typeof(CorePilot).GetField("state",f).GetValue(app);Check(!app.IsDisposed&&state.Text.Contains("2 个进程"),"exit waits and reports processes that are still being restored");update.Invoke(app,new object[]{new CycleResult()});Check(app.IsDisposed,"application exits automatically when recovery finishes");}
 [STAThread]static void Main(){Application.EnableVisualStyles();AppStore.TestDirectory=Path.Combine(Path.GetTempPath(),"CorePilot-refresh-"+Guid.NewGuid().ToString("N"));var cpus=Native.Topology();AppStore.Write(AppStore.FilePath,new Settings{CCD0=cpus.Take(12).Select(c=>c.Key).ToArray(),CCD1=cpus.Skip(12).Select(c=>c.Key).ToArray()});using(var app=new CorePilot(false,true)){
 var timer=(Timer)typeof(CorePilot).GetField("timer",f).GetValue(app);var refreshButton=(MotionButton)typeof(CorePilot).GetField("refreshButton",f).GetValue(app);Check(timer.Interval==5000,"automatic refresh interval is reduced to five seconds");Check(refreshButton!=null&&refreshButton.Text=="立即刷新","running page exposes a manual refresh button");
 var list=Enumerable.Range(0,100).Select(i=>new ProcessView{Process=new Entry{Path="D:\\Test\\App"+i.ToString("D3")+".exe",Product="App"+i.ToString("D3"),Id=1000+i},Grant=new Grant{Rule=new Rule{Preset="CCD1"}},Status="已校验"}).ToList();
 typeof(CorePilot).GetField("current",f).SetValue(app,list);app.Show();Application.DoEvents();Action render=()=>typeof(CorePilot).GetMethod("RenderRows",f).Invoke(app,null);render();var grid=(DataGridView)typeof(CorePilot).GetField("grid",f).GetValue(app);grid.ClearSelection();grid.Rows[55].Selected=true;grid.FirstDisplayedScrollingRowIndex=50;var anchor=grid.Rows[50];var selected=grid.Rows[55];var original=grid.Rows.Cast<DataGridViewRow>().ToArray();for(int i=0;i<40;i++)render();Check(original.SequenceEqual(grid.Rows.Cast<DataGridViewRow>()),"40 unchanged refreshes retain every row object");Check(grid.FirstDisplayedScrollingRowIndex==50&&selected.Selected,"scroll and selection survive unchanged refreshes");list.Add(new ProcessView{Process=new Entry{Path="D:\\Test\\A.exe",Product="A",Id=900},Grant=new Grant{Rule=new Rule{Preset="All"}},Status="已校验"});render();Check(grid.Rows[grid.FirstDisplayedScrollingRowIndex]==anchor&&selected.Selected,"insertion before viewport preserves anchor and selection");list.RemoveAt(0);render();Check(grid.Rows[grid.FirstDisplayedScrollingRowIndex]==anchor&&selected.Selected,"removal before viewport preserves anchor and selection");list[60].Grant.Rule.Preset="All";render();Check(grid.Rows.Cast<DataGridViewRow>().Any(r=>Convert.ToString(r.Cells[3].Value)=="全部 CPU"),"changed allocation updates in place");var until=DateTime.UtcNow.AddMilliseconds(350);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}Check(grid.Rows.Cast<DataGridViewRow>().All(r=>r.DefaultCellStyle.BackColor.IsEmpty),"refresh animation settles to normal background");CheckSettingsLayout(app);CheckExitProgress(app);}Console.WriteLine("ALL PASS");}
}

